'use client';

import React, { useState } from 'react';
import { X, AlertCircle, Send, Toilet, Droplets, Banknote, ShieldAlert, Loader2 } from 'lucide-react';
import { clsx } from 'clsx';
import axios from 'axios';
import { API_BASE } from '@/lib/api';

interface TwitterComplaintModalProps {
  isOpen: boolean;
  onClose: () => void;
  trainNo: string;
  pnr?: string;
}

const ISSUES = [
  { id: 'toilet', label: 'Dirty Toilet', icon: Toilet, emoji: '🚽' },
  { id: 'water', label: 'No Water', icon: Droplets, emoji: '💧' },
  { id: 'overcharge', label: 'Overcharging', icon: Banknote, emoji: '💰' },
  { id: 'security', label: 'Security Issue', icon: ShieldAlert, emoji: '🚨' }
];

export function TwitterComplaintModal({ isOpen, onClose, trainNo, pnr }: TwitterComplaintModalProps) {
  const [selectedIssue, setSelectedIssue] = useState<string | null>(null);
  const [coach, setCoach] = useState('');
  const [seat, setSeat] = useState('');
  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  const handleTweet = async () => {
    if (!selectedIssue || !coach || !seat) return;
    
    setLoading(true);
    const issue = ISSUES.find(i => i.id === selectedIssue);
    const tweetContent = `@RailMinIndia @RailMadad 🚆\n\nTrain ${trainNo}\nCoach ${coach}\nSeat ${seat}\n\nIssue: ${issue?.label} ${issue?.emoji}\n\nPlease take action urgently.\n\nReported via Trayago 🚆`;
    
    const url = `https://twitter.com/intent/tweet?text=${encodeURIComponent(tweetContent)}`;

    try {
      // 1. Log the complaint in our DB
      await axios.post(`${API_BASE}/analytics/complaint`, {
        pnr,
        train_no: trainNo,
        issue_type: issue?.label,
        tweet_content: tweetContent
      });

      // 2. Open Twitter
      window.open(url, '_blank');
      onClose();
    } catch (err) {
      console.error('Failed to log complaint', err);
      window.open(url, '_blank');
      onClose();
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 animate-in fade-in duration-300">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-md" onClick={onClose} />
      
      <div className="relative w-full max-w-lg bg-card border border-subtle rounded-[2.5rem] shadow-2xl p-8 overflow-hidden">
        {/* Header */}
        <div className="flex justify-between items-start mb-8">
           <div className="space-y-1">
             <h2 className="text-main text-2xl font-black tracking-tight flex items-center">
                <AlertCircle className="text-red-500 mr-2" />
                Report <span className="text-red-500 ml-1">Issue</span>
             </h2>
             <p className="text-muted text-xs font-semibold">Immediate social accountability via Twitter (X)</p>
           </div>
           <button onClick={onClose} className="p-2 bg-input rounded-full hover:bg-input/80 transition-colors">
              <X size={20} className="text-muted" />
           </button>
        </div>

        {/* Issue Selection */}
        <div className="grid grid-cols-2 gap-3 mb-8">
           {ISSUES.map((issue) => (
              <button
                 key={issue.id}
                 onClick={() => setSelectedIssue(issue.id)}
                 className={clsx(
                   "p-4 rounded-2xl border transition-all duration-300 flex flex-col items-center space-y-2",
                   selectedIssue === issue.id 
                     ? "bg-red-500/10 border-red-500/40 text-main" 
                     : "bg-input/50 border-subtle text-muted hover:border-strong"
                 )}
              >
                 <issue.icon size={24} className={selectedIssue === issue.id ? "text-red-500" : ""} />
                 <span className="text-[10px] font-black uppercase tracking-widest">{issue.label}</span>
              </button>
           ))}
        </div>

        {/* Coach/Seat Inputs */}
        <div className="grid grid-cols-2 gap-4 mb-8">
           <div className="space-y-2">
              <label className="text-muted text-[10px] font-black uppercase tracking-[0.2em] ml-2">Coach No</label>
              <input 
                type="text" 
                placeholder="e.g. S4, B1"
                value={coach}
                onChange={(e) => setCoach(e.target.value)}
                className="w-full bg-input border border-subtle rounded-2xl py-3 px-5 text-sm font-bold text-main outline-none focus:border-red-500 transition-all placeholder:text-muted/60 font-mono uppercase"
              />
           </div>
           <div className="space-y-2">
              <label className="text-muted text-[10px] font-black uppercase tracking-[0.2em] ml-2">Seat No</label>
              <input 
                type="number" 
                placeholder="e.g. 42"
                value={seat}
                onChange={(e) => setSeat(e.target.value)}
                className="w-full bg-input border border-subtle rounded-2xl py-3 px-5 text-sm font-bold text-main outline-none focus:border-red-500 transition-all placeholder:text-muted/60"
              />
           </div>
         </div>

        {/* Action Button */}
        <button
          onClick={handleTweet}
          disabled={!selectedIssue || !coach || !seat || loading}
          className={clsx(
            "w-full py-5 rounded-2xl flex items-center justify-center space-x-3 transition-all active:scale-95 text-xs font-black uppercase tracking-[0.2em]",
            (!selectedIssue || !coach || !seat) 
              ? "bg-input text-muted cursor-not-allowed" 
              : "bg-red-600 hover:bg-red-500 text-main shadow-2xl shadow-red-600/30"
          )}
        >
          {loading ? (
            <Loader2 className="animate-spin" size={18} />
          ) : (
            <>
              <Send size={18} />
              <span>Blast to Twitter</span>
            </>
          )}
        </button>

        <p className="mt-6 text-center text-muted text-[8px] font-bold uppercase tracking-widest leading-relaxed">
          This will open Twitter (X) with your draft content.<br/> Trayago does not tweet automatically.
        </p>
      </div>
    </div>
  );
}
