import React from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'success' | 'danger' | 'premium' | 'ghost' | 'outline';
  size?: 'sm' | 'md' | 'lg';
  loading?: boolean;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant = 'primary', size = 'md', loading, children, ...props }, ref) => {
    // Uiverse-style CSS hover shine sweep (Source: https://uiverse.io/ - pure GPU CSS, zero JS overhead, respects reduced motion)
    const baseStyle = 'relative overflow-hidden inline-flex items-center justify-center font-black uppercase tracking-widest text-[11px] transition-all duration-200 select-none active:scale-97 disabled:opacity-50 disabled:pointer-events-none rounded-xl outline-none after:absolute after:inset-0 after:-translate-x-full hover:after:translate-x-full after:transition-transform after:duration-700 after:bg-gradient-to-r after:from-transparent after:via-white/15 after:to-transparent motion-reduce:after:hidden';
    
    const variants = {
      primary: 'bg-primary text-white hover:bg-primary/95 shadow-md shadow-primary/10 focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-card',
      secondary: 'bg-input text-main border border-strong hover:bg-card focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-card',
      success: 'bg-success text-white hover:bg-success/95 shadow-md shadow-success/10 focus-visible:ring-2 focus-visible:ring-success focus-visible:ring-offset-2 focus-visible:ring-offset-card',
      danger: 'bg-danger text-white hover:bg-danger/95 shadow-md shadow-danger/10 focus-visible:ring-2 focus-visible:ring-danger focus-visible:ring-offset-2 focus-visible:ring-offset-card',
      premium: 'bg-gradient-to-r from-premium to-primary text-white hover:opacity-95 shadow-lg shadow-premium/15 focus-visible:ring-2 focus-visible:ring-premium focus-visible:ring-offset-2 focus-visible:ring-offset-card',
      ghost: 'bg-transparent text-secondary hover:bg-input hover:text-main focus-visible:ring-2 focus-visible:ring-primary',
      outline: 'bg-transparent border border-strong text-main hover:bg-input focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-card',
    };

    const sizes = {
      sm: 'min-h-[44px] h-11 px-4 text-xs',
      md: 'min-h-[48px] h-12 px-6',
      lg: 'min-h-[56px] h-14 px-8 text-xs',
    };

    return (
      <button
        ref={ref}
        className={cn(baseStyle, variants[variant], sizes[size], className)}
        disabled={loading || props.disabled}
        {...props}
      >
        {loading ? (
          <span className="w-3.5 h-3.5 border-2 border-current border-t-transparent rounded-full animate-spin mr-2 shrink-0" />
        ) : null}
        {children}
      </button>
    );
  }
);

Button.displayName = 'Button';
